// A child's full MOH vaccination schedule, generated by the database from the
// birth date. Tap a dose to mark it given or change its date.
import { router, useLocalSearchParams } from 'expo-router';
import { useState } from 'react';
import { View } from 'react-native';
import { Button, Card, ErrorText, Muted, Row, Screen, Skeleton, Title, Txt } from '@/components/ui';
import { getChild, getCurrentSchedule, listChildVaccinations, markPastDosesDone, type ChildVaccination } from '@/lib/api';
import { confirm } from '@/lib/confirm';
import { toDay } from '@/lib/dates';
import { formatDay, useI18n } from '@/lib/i18n';
import { useLoad } from '@/lib/useLoad';
import { colors, space } from '@/theme';
import { HealthNote } from '@/components/HealthNote';

export default function Vaccines() {
  const { t, locale } = useI18n();
  const { childId } = useLocalSearchParams<{ childId: string }>();
  const [busy, setBusy] = useState(false);
  const { data, error, reload } = useLoad(
    () => Promise.all([getChild(childId), listChildVaccinations(childId), getCurrentSchedule()]),
    [childId],
  );

  if (error) return <Screen><ErrorText>{t.somethingWrong}</ErrorText><Button title={t.retry} onPress={reload} /></Screen>;
  if (!data) return <Screen><Skeleton lines={6} /></Screen>;
  const [child, doses, schedule] = data;
  const today = toDay(new Date());
  const pastOpen = doses.filter((d) => d.status === 'due' && d.due_date < today).length;

  // Group doses that share a due date ("2 months", "4 months", …).
  const groups: { day: string; doses: ChildVaccination[] }[] = [];
  for (const d of doses) {
    const last = groups[groups.length - 1];
    if (last && last.day === d.due_date) last.doses.push(d);
    else groups.push({ day: d.due_date, doses: [d] });
  }

  return (
    <Screen>
      <HealthNote />
      <Title>{child.first_name}</Title>
      <Card style={{ backgroundColor: colors.sand, borderColor: colors.sand }}>
        <Txt style={{ fontSize: 14 }}>{t.scheduleDisclaimer}</Txt>
        {schedule ? (
          <Muted>
            {t.scheduleSource}: {locale === 'ar' ? schedule.title_ar : schedule.title_en}
            {(locale === 'ar' ? schedule.review_note_ar : schedule.review_note_en) ? `\n${locale === 'ar' ? schedule.review_note_ar : schedule.review_note_en}` : ''}
          </Muted>
        ) : null}
      </Card>

      {pastOpen > 0 ? (
        <Button
          title={`${t.markPastDone} (${pastOpen})`}
          variant="secondary"
          loading={busy}
          onPress={async () => {
            if (!(await confirm(t.markPastDoneConfirm, t))) return;
            setBusy(true);
            try {
              await markPastDosesDone(childId, today);
              reload();
            } finally {
              setBusy(false);
            }
          }}
        />
      ) : null}

      {groups.map((g) => (
        <View key={g.day} style={{ gap: space.sm }}>
          <Txt style={{ fontWeight: '700', color: colors.tealDark }}>{formatDay(g.day, locale)}</Txt>
          {g.doses.map((d) => {
            const overdue = d.status === 'due' && d.due_date < today;
            const statusText = d.status === 'done' ? `✓ ${t.statusDone}` : d.status === 'skipped' ? t.statusSkipped : overdue ? t.overdue : t.statusDue;
            const statusColor = d.status === 'done' ? colors.success : overdue ? colors.danger : colors.muted;
            return (
              <Card key={d.id} onPress={() => router.push(`/dose/${d.id}`)}>
                <Row>
                  <Txt style={{ flex: 1, fontWeight: '600' }}>{locale === 'ar' ? d.vaccine_doses.name_ar : d.vaccine_doses.name_en}</Txt>
                  <Txt style={{ color: statusColor, fontWeight: '700', fontSize: 14 }}>{statusText}</Txt>
                </Row>
                <Muted>{locale === 'ar' ? d.vaccine_doses.dose_label_ar : d.vaccine_doses.dose_label_en}</Muted>
              </Card>
            );
          })}
        </View>
      ))}
    </Screen>
  );
}
